/* Open Room ETHZ service worker: the static app shell, versioned. See docs/UPDATES.md.
 *
 * Versioning: /sw-version.js (generated by scripts/stamp-version.mjs from a hash of every shipped file) defines OPENROOM_VERSION and the
 * precache list. Importing it makes this file's update check see new bytes whenever ANY shipped file changes; a byte-identical sw.js
 * alone would not notice a changed stylesheet or script.
 *
 * Consistency: every shell file is served from this version's own cache (precached completely at install). A page therefore always gets
 * a complete old OR a complete new set of files, never a mix. A new worker waits until the page asks for it (SKIP_WAITING) so the app can
 * reload exactly once, at a safe moment.
 *
 * Never cached or served from here: /api/ (availability must come from the network or the app's own age-tracked cache) and /version.json
 * (the update check needs the network). Only successful same-origin responses are ever stored; errors and redirects never are. */
importScripts('/sw-version.js');

const VERSION = self.OPENROOM_VERSION;
const ASSETS = self.OPENROOM_ASSETS;
const CACHE = `openroom-shell-${VERSION}`;
const ASSET_SET = new Set(ASSETS);

self.addEventListener('install', event => {
  // NO skipWaiting() here: activation is requested by the page.
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await Promise.all(ASSETS.map(async url => {
      const response = await fetch(new Request(url, {cache: 'reload'})); // bypass the HTTP cache: precache exactly what is deployed now
      if (!response.ok || response.type !== 'basic' || response.redirected) throw new Error(`precache failed for ${url}: ${response.status}`);
      await cache.put(url, response);
    }));
  })()); // if any file is missing (for example right after a deployment) the install fails and the old version keeps running
});

self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') self.skipWaiting();
  if (event.data?.type === 'GET_VERSION') event.source?.postMessage({type: 'VERSION', version: VERSION});
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(n => n !== CACHE && (n.startsWith('openroom-shell-') || n.startsWith('openroom-static-'))).map(n => caches.delete(n)));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.startsWith('/api/') || url.pathname === '/version.json') return; // straight to the network
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const path = url.pathname;
    if (request.mode === 'navigate' && (path === '/' || path === '/index.html')) {
      return (await cache.match('/')) || fetch(request);  // the start page is cached as '/' (index.html redirects there on Cloudflare)
    }
    if (ASSET_SET.has(path)) {
      const hit = await cache.match(path);
      if (hit) return hit;
    }
    try { return await fetch(request); }
    catch {
      if (request.mode === 'navigate') return (await cache.match('/')) || Response.error();
      return Response.error();
    }
  })());
});
